FILES = {'RUN6_mk_run6.py': '"""RUN6 generator (Grok, green_regular_character lane). Reads upstream files fetched at pin\n40e56bab026552e089d7afcfeff08d2defb9c005 into /workspace/rh_green_up and writes GreenCompanion/Run6.lean.\nTextual operations only: proof bodies sliced verbatim; namespace prefixes renamed; remaining upstream dependency\nreferences renamed to hypotheses whose Prop-def text is the exact upstream statement."""\nU = "/workspace/rh_green_up/src/Development/AbelianVarietyTheory/"\nL = "/workspace/rh_green_lean/GreenCompanion/"\nCT = "Proofs/CharacterTheory/"; FM = "Proofs/FlagMeasures/"\ndef rd(p): return open(U + p).read()\ndef body(p, ns, first=False):\n    t = rd(p); key = "namespace " + ns + "\\n"\n    a = t.index(key) + len(key); b = t.index("end " + ns, a) if first else t.rindex("end " + ns)\n    return t[a:b].strip("\\n") + "\\n"\ndef stmt(p, name):\n    t = rd(p); key = "theorem _root_.GlobalTheory.T." + name + " : "\n    a = t.index(key) + len(key); b = t.index(" := by", a)\n    return t[a:b]\ndef sub(t, pairs):\n    for x, y in pairs:\n        assert x in t, x\n        t = t.replace(x, y)\n    return t\n\nfca = stmt(CT + "MonicFactorizationConvolutionFiniteCommAssocAddStatement.lean", "monicFactorizationConvolution_finite_comm_assoc_add")\nvm1 = stmt(CT + "AdditiveEqPolynomialVonMangoldtConvolutionOneStatement.lean", "additive_eq_polynomialVonMangoldt_convolution_one")\n\ncyc = body(CT + "FinsumCardCyclicVectorsInvariantSubspaces.lean", "GlobalTheory.CuspGL")\nmc1 = body(CT + "EndomorphismMassOfCharpolyCardCyclicVectors.lean", "GlobalTheory.CuspGL.CyclicMass")\nt = rd(CT + "EndomorphismMassOfCharpolyCardCyclicVectors.lean")\na = t.index("namespace GlobalTheory.CuspGL\\n") + len("namespace GlobalTheory.CuspGL\\n"); b = t.rindex("end GlobalTheory.CuspGL")\nmc2 = t[a:b].strip("\\n") + "\\n"\nmeq = body(CT + "EndomorphismMassEqOfLinearEquivInvariant.lean", "GlobalTheory.CuspGL")\nlogd = sub(body(CT + "AdditiveMulEqVonMangoldtConvolution.lean", "GlobalTheory.CuspGL.LogDeriv"), [\n    ("GlobalTheory.T.monicFactorizationConvolution_finite_comm_assoc_add", "FinCommH.h"),\n    ("GlobalTheory.T.additive_eq_polynomialVonMangoldt_convolution_one", "VonMangoldtOneH.h")])\nlogd = sub(logd, [("variable {F : Type} [Field F]\\n", "variable {F : Type} [Field F]\\nvariable [hFC : FinCommH] [hVM : VonMangoldtOneH]\\ninclude hFC hVM\\n")])\ndcl = sub(body(FM + "IsClassFunctionBernsteinZelevinskyDerivative.lean", "GlobalTheory.GLm.DerClass"), [\n    ("_root_.GlobalTheory.GLm.DerClass.", ""), ("_root_.GlobalTheory.GLq.Mt", "Mt")])\n\nmtail = stmt(FM + "MirabolicFunctionEqInducedDerivativeAddTailStatement.lean", "mirabolic_function_eq_induced_derivative_add_tail")\nphip = stmt(FM + "MirabolicInductionPhiPlusInductionFromBlockUniStatement.lean", "mirabolicInductionPhiPlus_inductionFromBlockUni")\ndtail = stmt(FM + "DerTailStatement.lean", "der_tail_of_lt_of_le")\ntmir = stmt(FM + "IsMirabolicConjInvariantTwistedTailMeanFunStatement.lean", "isMirabolicConjInvariant_twistedTailMeanFun")\nbpar = stmt(FM + "BlockParabolicUnitriangularSubgroupsGLnPrimeFielStatement.lean", "blockParabolic_unitriangular_subgroups_GLnPrimeField")\nim = rd("Definitions/SemilocalFrames/IsMirClass.lean")\ndef grab(start, endmark="\\n\\n"):\n    a = im.index(start); b = im.index(endmark, a); return im[a:b] + "\\n"\ntailD = grab("def tail "); indVD = grab("def indV "); inMir1 = grab("theorem inMir_one ", "\\n") \nmirsum = sub(body(FM + "MirabolicConjInvariantEqSumInducedDerivatives.lean", "GlobalTheory.GLm.MirSum"), [\n    ("theorem eq_sum_indR_der : ", "theorem eq_sum_indR_der (hTM : TailMirPart) (hMT : MirTailPart) (hPP : PhiPlusPart) (hDT : DerTailPart) : "),\n    ("GlobalTheory.T.isMirabolicConjInvariant_twistedTailMeanFun", "hTM"),\n    ("GlobalTheory.T.mirabolic_function_eq_induced_derivative_add_tail", "hMT"),\n    ("GlobalTheory.T.mirabolicInductionPhiPlus_inductionFromBlockUni", "hPP"),\n    ("GlobalTheory.T.der_tail_of_lt_of_le", "hDT")])\nMI = FM + "MirabolicInductionBlockDiagEqHarishChandraGelfan.lean"\nresind = sub(body(MI, "GlobalTheory.GLm.ResInd"), [\n    ("open Polynomial Formalism.MainNotions.ArithmeticCylinders GlobalTheory.GLq GlobalTheory.GLm\\n", "open Polynomial GreenCompanion.GLm\\n"),\n    ("variable {g : ℕ} [Fact g.Prime]\\n", "variable {g : ℕ} [Fact g.Prime]\\nvariable [hBP : BlockParH]\\ninclude hBP\\n"),\n    ("GlobalTheory.T.blockParabolic_unitriangular_subgroups_GLnPrimeField", "BlockParH.h")])\nmt = rd(MI); a = mt.index("namespace GlobalTheory.GLm\\n") + len("namespace GlobalTheory.GLm\\n"); b = mt.rindex("end GlobalTheory.GLm")\nmind_main = sub(mt[a:b].strip("\\n") + "\\n", [\n    ("open Polynomial Formalism.MainNotions.ArithmeticCylinders GlobalTheory.GLq GlobalTheory.GLm.ResInd\\nopen scoped Classical\\n",\n     "open Polynomial GreenCompanion.GLm.ResInd\\nopen scoped Classical\\nvariable [hBP : BlockParH]\\ninclude hBP\\n")])\n\nout = f"""/-\nGreen lane RUN6 companion (Grok, 2026-11-24). Generated by RUN6_mk_run6.py from upstream\nleanprover-community/riemann-hypothesis @ 40e56bab026552e089d7afcfeff08d2defb9c005:\n  Proofs/CharacterTheory/FinsumCardCyclicVectorsInvariantSubspaces.lean   (CuspGL.finsum_card_cyclic_eq)\n  Proofs/CharacterTheory/EndomorphismMassOfCharpolyCardCyclicVectors.lean (CuspGL.CyclicMass.*, CuspGL.mass_card_cyclic)\n  Proofs/CharacterTheory/EndomorphismMassEqOfLinearEquivInvariant.lean    (CuspGL.mass_eq_mass_pi_of_invariant)\n  Proofs/CharacterTheory/AdditiveMulEqVonMangoldtConvolution.lean         (CuspGL.LogDeriv.*)\n  Proofs/FlagMeasures/IsClassFunctionBernsteinZelevinskyDerivative.lean   (GLm.DerClass.*)\n  Proofs/FlagMeasures/MirabolicConjInvariantEqSumInducedDerivatives.lean  (GLm.MirSum.*)\n  Proofs/FlagMeasures/MirabolicInductionBlockDiagEqHarishChandraGelfan.lean (GLm.ResInd.*, GLm.indR_diag1_eq_hc_gg)\n  Definitions/SemilocalFrames/IsMirClass.lean (defs tail, indV and theorem inMir_one, verbatim)\nProof bodies verbatim (only namespace prefixes `_root_.GlobalTheory.GLm.DerClass.` / `_root_.GlobalTheory.GLq.Mt`\nshortened). In LogDeriv (and ResInd, via `BlockParH`) the upstream dependencies are supplied as Prop-valued classes `FinCommH`, `VonMangoldtOneH`\nwhose field type is the exact upstream statement (so that the verbatim helper-lemma call sites need no edits).\nDefinitions come from earlier runs\' modules (verbatim upstream definitions). No sorry, no axiom.\n-/\nimport GreenCompanion.Run5\n\nnoncomputable section\nopen Polynomial\n\nnamespace GreenCompanion\n\nsection CuspPart\nopen CuspGL\n\n/-- exact statement of upstream `GlobalTheory.T.monicFactorizationConvolution_finite_comm_assoc_add`. -/\ndef FinCommPart : Prop := {fca}\n/-- exact statement of upstream `GlobalTheory.T.additive_eq_polynomialVonMangoldt_convolution_one`. -/\ndef VonMangoldtOnePart : Prop := {vm1}\n\n/-- carrier class for the hypothesis `FinCommPart` (used only to thread it through verbatim helper lemmas). -/\nclass FinCommH : Prop where\n  h : FinCommPart\n/-- carrier class for the hypothesis `VonMangoldtOnePart`. -/\nclass VonMangoldtOneH : Prop where\n  h : VonMangoldtOnePart\n\nnamespace CuspGL\n\n{cyc}\nnamespace CyclicMass\n\nvariable {{F : Type}} [Field F]\n""" + mc1.replace("variable {F : Type} [Field F]\\n", "", 1) + f"""\nend CyclicMass\n\n{mc2}\n{meq}\nnamespace LogDeriv\n\n{logd}\nend LogDeriv\n\nend CuspGL\n\n/-- RUN5 leaf `T.finsum_card_cyclic_vectors_invariant_subspaces` (`CycSumPart`), proved. -/\ntheorem cycSumPart_holds : CycSumPart := CuspGL.finsum_card_cyclic_eq\n/-- RUN5 leaf `T.endomorphismMassOfCharpoly_card_cyclic_vectors` (`MassCycPart`), proved. -/\ntheorem massCycPart_holds : MassCycPart := CuspGL.mass_card_cyclic\n/-- RUN4 leaf `T.endomorphismMass_eq_of_linearEquiv_invariant` (`MassEqPart`), proved. -/\ntheorem massEqPart_holds : MassEqPart := CuspGL.mass_eq_mass_pi_of_invariant\n/-- RUN4 leaf `T.additive_mul_eq_vonMangoldt_convolution` (`LogConvPart`) from its two upstream deps. -/\ntheorem logConvPart_of_deps (h1 : FinCommPart) (h2 : VonMangoldtOnePart) : LogConvPart := by\n  haveI : FinCommH := ⟨h1⟩\n  haveI : VonMangoldtOneH := ⟨h2⟩\n  exact CuspGL.LogDeriv.additive_mul_eq_conv\n/-- RUN4 leaf `T.charpolyEndomorphismDensityGL_recursion` (`MuRecPart`), now only from `ParMassPart`. -/\ntheorem muRecPart_of_parMass (hParMass : ParMassPart) : MuRecPart :=\n  muRecPart_of_deps hParMass cycSumPart_holds massCycPart_holds\n/-- RUN3 `MassPart` (= upstream `T.endomorphismMass_mobiusInverse_monic_eq`) from the current leaves. -/\ntheorem massPart_of_leaves6 (hConj : ConjPart) (hParMass : ParMassPart) (hPsiSum : PsiSumPart)\n    (h1 : FinCommPart) (h2 : VonMangoldtOnePart) : MassPartR3 :=\n  massPart_of_leaves hConj (logConvPart_of_deps h1 h2) hParMass hPsiSum massEqPart_holds cycSumPart_holds massCycPart_holds\n\nend CuspPart\n\nnamespace GLm.DerClass\nopen scoped Classical\n\n{dcl}\nend GLm.DerClass\n\n/-- RUN5 leaf `T.isClassFunction_bernsteinZelevinskyDerivative` (`DerClassPart`), proved. -/\ntheorem derClassPart_holds : DerClassPart := GLm.DerClass.isClass_der\n\n/-- RUN3 `SumWhGGPart` (= upstream `GLm.GGSum.sum_wh_gg`) from the current leaves. -/\ntheorem sumWhGGPart_of_leaves6 (hWJ : WJPart) (hWhMul : WhMulPart) (hBZ : BZPart) (hMConj : MirConjPart)\n    (hMInd : MirIndPart) : SumWhGGPart :=\n  sumWhGGPart_of_leaves hWJ hWhMul hBZ hMConj hMInd derClassPart_holds\n\nsection MirDefs\nopen scoped Classical\nvariable {{g : ℕ}} [Fact g.Prime]\n\n{tailD}\n{indVD}\n{inMir1}\nend MirDefs\n\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.mirabolic_function_eq_induced_derivative_add_tail`. -/\ndef MirTailPart : Prop := {mtail}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.mirabolicInductionPhiPlus_inductionFromBlockUni`. -/\ndef PhiPlusPart : Prop := {phip}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.der_tail_of_lt_of_le`. -/\ndef DerTailPart : Prop := {dtail}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.isMirabolicConjInvariant_twistedTailMeanFun`. -/\ndef TailMirPart : Prop := {tmir}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.blockParabolic_unitriangular_subgroups_GLnPrimeField`. -/\ndef BlockParPart : Prop := {bpar}\n/-- carrier class for the hypothesis `BlockParPart` (threads it through verbatim helper lemmas). -/\nclass BlockParH : Prop where\n  h : BlockParPart\n\nnamespace GLm.MirSum\nopen scoped Classical\nvariable {{g : ℕ}} [Fact g.Prime]\n\n{mirsum}\nend GLm.MirSum\n\nnamespace GLm.ResInd\n\n{resind}\nend GLm.ResInd\n\nnamespace GLm\n\n{mind_main}\nend GLm\n\n/-- RUN5 leaf `T.mirabolicConjInvariant_eq_sum_induced_derivatives` (`MirConjPart`) from its four upstream deps. -/\ntheorem mirConjPart_of_deps (hTM : TailMirPart) (hMT : MirTailPart) (hPP : PhiPlusPart) (hDT : DerTailPart) :\n    MirConjPart :=\n  GLm.MirSum.eq_sum_indR_der hTM hMT hPP hDT\n/-- RUN5 leaf `T.mirabolicInduction_blockDiag_eq_harishChandra_gelfandGraev` (`MirIndPart`) from its upstream dep. -/\ntheorem mirIndPart_of_deps (hBPp : BlockParPart) : MirIndPart := by\n  haveI : BlockParH := ⟨hBPp⟩\n  exact GLm.indR_diag1_eq_hc_gg\n/-- RUN4 leaf `T.mirabolicClassFun_blockDiagonal_eq_sum_derivatives` (`MirPart`) from the current leaves. -/\ntheorem mirPart_of_leaves6 (hTM : TailMirPart) (hMT : MirTailPart) (hPP : PhiPlusPart) (hDT : DerTailPart)\n    (hBPp : BlockParPart) : MirPart :=\n  mirPart_of_deps (mirConjPart_of_deps hTM hMT hPP hDT) (mirIndPart_of_deps hBPp) derClassPart_holds\n/-- RUN3 `SumWhGGPart` (= upstream `GLm.GGSum.sum_wh_gg`) from the current leaves (RUN6). -/\ntheorem sumWhGGPart_of_leaves6\' (hWJ : WJPart) (hWhMul : WhMulPart) (hBZ : BZPart) (hTM : TailMirPart)\n    (hMT : MirTailPart) (hPP : PhiPlusPart) (hDT : DerTailPart) (hBPp : BlockParPart) : SumWhGGPart :=\n  sumWhGGPart_of_deps hWJ hWhMul hBZ (mirPart_of_leaves6 hTM hMT hPP hDT hBPp)\n\nend GreenCompanion\n\n#print axioms GreenCompanion.CuspGL.finsum_card_cyclic_eq\n#print axioms GreenCompanion.CuspGL.mass_card_cyclic\n#print axioms GreenCompanion.CuspGL.mass_eq_mass_pi_of_invariant\n#print axioms GreenCompanion.CuspGL.LogDeriv.additive_mul_eq_conv\n#print axioms GreenCompanion.GLm.DerClass.isClass_der\n#print axioms GreenCompanion.cycSumPart_holds\n#print axioms GreenCompanion.massCycPart_holds\n#print axioms GreenCompanion.massEqPart_holds\n#print axioms GreenCompanion.logConvPart_of_deps\n#print axioms GreenCompanion.muRecPart_of_parMass\n#print axioms GreenCompanion.massPart_of_leaves6\n#print axioms GreenCompanion.derClassPart_holds\n#print axioms GreenCompanion.sumWhGGPart_of_leaves6\n#print axioms GreenCompanion.GLm.MirSum.eq_sum_indR_der\n#print axioms GreenCompanion.GLm.indR_diag1_eq_hc_gg\n#print axioms GreenCompanion.mirConjPart_of_deps\n#print axioms GreenCompanion.mirIndPart_of_deps\n#print axioms GreenCompanion.mirPart_of_leaves6\n#print axioms GreenCompanion.sumWhGGPart_of_leaves6\'\n"""\nopen(L + "Run6.lean", "w").write(out)\nprint("wrote", L + "Run6.lean", len(out))\n', 'RUN6_green_exact_checks.py': '"""RUN6 exact finite checks (green_regular_character lane). Exact integer / Fraction arithmetic only; exhaustive\nover all monic polynomials of bounded degree over F_p. Small-case illustrations of the RUN6 statements; not proofs.\n (E) additive_mul_eq_vonMangoldt_convolution: for q in {2,3,7} (q need not equal |F|), m defined by m(1)=1 and\n     q^deg P m(P) = (1*m)(P), and additive s in {natDegree, mult. of root 0, mult. of root 1, #irreducible factors\n     with multiplicity}: s(P) m(P) = (L*m)(P) with L(D) = mangoldt s D / (q^deg D - 1).\n (F) leaf additive_eq_polynomialVonMangoldt_convolution_one, first clause: s(P) = (mangoldt s * 1)(P).\n (G) leaf monicFactorizationConvolution_finite_comm_assoc_add (comm/assoc/additivity clauses) on fixed integer-valued\n     test functions a(P)=deg P+1, b(P)=P(0)+2, c(P)=(sum of coefficients)+1 (as integers 0..p-1)."""\nfrom fractions import Fraction\nfrom itertools import product\n\ndef pmul(a, b, p):\n    r = [0] * (len(a) + len(b) - 1)\n    for i, x in enumerate(a):\n        for j, y in enumerate(b): r[i + j] = (r[i + j] + x * y) % p\n    return tuple(r)\ndef monics(d, p):\n    for c in product(range(p), repeat=d): yield tuple(c) + (1,)\ndef all_monics(dmax, p): return [P for d in range(dmax + 1) for P in monics(d, p)]\ndef pairs(P, p):\n    d = len(P) - 1\n    return [(D, E) for e in range(d + 1) for D in monics(d - e, p) for E in monics(e, p) if pmul(D, E, p) == P]\ndef conv(a, b, P, p): return sum(a(D) * b(E) for D, E in pairs(P, p))\nIRR = {}\ndef is_irred(f, p):\n    k = (f, p)\n    if k not in IRR:\n        d = len(f) - 1\n        IRR[k] = d >= 1 and all(pmul(a, b, p) != f for e in range(1, d // 2 + 1) for a in monics(e, p) for b in monics(d - e, p))\n    return IRR[k]\ndef factor(P, p):  # multiset of monic irreducible factors\n    out = []; d = len(P) - 1\n    for e in range(1, d + 1):\n        for f in monics(e, p):\n            if not is_irred(f, p): continue\n            while True:\n                Q = next((E for E in monics(len(P) - 1 - e, p) if pmul(f, E, p) == P), None) if len(P) - 1 >= e else None\n                if Q is None: break\n                out.append(f); P = Q\n    return out\ndef mangoldt(s, P, p):\n    fs = factor(P, p)\n    return s(fs[0]) if fs and all(f == fs[0] for f in fs) else 0\ndef svals(p):\n    return {"natDegree": lambda P: len(P) - 1,\n            "mult root 0": lambda P: sum(1 for f in factor(P, p) if f == (0, 1)),\n            "mult root 1": lambda P: sum(1 for f in factor(P, p) if f == ((p - 1) % p, 1)),\n            "Omega": lambda P: len(factor(P, p))}\n\ndef check_E(p, dmax, q):\n    Ps = all_monics(dmax, p); m = {}\n    for P in sorted(Ps, key=len):\n        if len(P) == 1: m[P] = Fraction(1); continue\n        rest = sum(m[E] for D, E in pairs(P, p) if E != P)\n        m[P] = rest / (q ** (len(P) - 1) - 1)\n    for name, s in svals(p).items():\n        L = lambda D: Fraction(mangoldt(s, D, p)) / (q ** (len(D) - 1) - 1) if len(D) > 1 else Fraction(0)\n        bad = sum(1 for P in Ps if s(P) * m[P] != conv(L, lambda E: m[E], P, p))\n        print(f"(E) p={p} deg<={dmax} q={q} s={name}: {len(Ps)} monic P, mismatches = {bad}")\ndef check_F(p, dmax):\n    Ps = all_monics(dmax, p)\n    for name, s in svals(p).items():\n        bad = sum(1 for P in Ps if s(P) != conv(lambda D: mangoldt(s, D, p), lambda E: 1, P, p))\n        print(f"(F) p={p} deg<={dmax} s={name}: {len(Ps)} monic P, mismatches = {bad}")\ndef check_G(p, dmax):\n    a = lambda P: len(P); b = lambda P: P[0] + 2; c = lambda P: sum(P) + 1\n    ab = lambda P: conv(a, b, P, p); bc = lambda P: conv(b, c, P, p)\n    bad = 0; Ps = all_monics(dmax, p)\n    for P in Ps:\n        bad += conv(a, b, P, p) != conv(b, a, P, p)\n        bad += conv(ab, c, P, p) != conv(a, bc, P, p)\n        bad += conv(lambda D: a(D) + b(D), c, P, p) != conv(a, c, P, p) + conv(b, c, P, p)\n        bad += conv(lambda D: a(D) - b(D), c, P, p) != conv(a, c, P, p) - conv(b, c, P, p)\n    print(f"(G) p={p} deg<={dmax}: {len(Ps)} monic P x 4 identities, mismatches = {bad}")\n\nif __name__ == "__main__":\n    for p, d in [(2, 4), (3, 3)]:\n        for q in (2, 3, 7): check_E(p, d, q)\n    for p, d in [(2, 5), (3, 3), (5, 2)]: check_F(p, d)\n    for p, d in [(2, 4), (3, 3)]: check_G(p, d)\n'}
for n, c in FILES.items():
    open(n, "w").write(c)
    print("wrote", n)
